Here is the commit message:
can: usb: f81604: correctly anchor the urb in the read bulk
 callback

When submitting an urb, that is using the anchor pattern, it needs to be
anchored before submitting it otherwise it could be leaked if
usb_kill_anchored_urbs() is called.  This logic is correctly done
elsewhere in the driver, except in the read bulk callback so do that
here also.

Cc: Ji-Ze Hong (Peter Hong) <peter_hong@fintek.com.tw>
Cc: Marc Kleine-Budde <mkl@pengutronix.de>
Cc: Vincent Mailhol <mailhol@kernel.org>
Cc: stable@kernel.org
Assisted-by: gkh_clanker_2000
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Link: https://patch.msgid.link/2026022334-starlight-scaling-2cea@gregkh
Fixes: 88da17436973 ("can: usb: f81604: add Fintek F81604 support")
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
URBs were submitted without first being anchored to the driver's anchor list, causing potential leaks or double-free when `usb_kill_anchored_urbs()` is called concurrently.

Here is the patch:

 static void f81604_read_bulk_callback(struct urb *urb)
 {
 	struct f81604_can_frame *frame = urb->transfer_buffer;
 	struct net_device *netdev = urb->context;
+	struct f81604_port_priv *priv = netdev_priv(netdev);
 	int ret;

 	if (!netif_device_present(netdev))
 		return;

 	if (urb->status)
 		netdev_info(netdev, "%s: URB aborted %pe\n", __func__,
 			    ERR_PTR(urb->status));

 	switch (urb->status) {
 	case 0: /* success */
 		break;

 	case -ENOENT:
 	case -EPIPE:
 	case -EPROTO:
 	case -ESHUTDOWN:
 		return;

 	default:
 		goto resubmit_urb;
 	}

 	if (urb->actual_length != sizeof(*frame)) {
 		netdev_warn(netdev, "URB length %u not equal to %zu\n",
 			    urb->actual_length, sizeof(*frame));
 		goto resubmit_urb;
 	}

 	f81604_process_rx_packet(netdev, frame);

 resubmit_urb:
+	usb_anchor_urb(urb, &priv->urbs_anchor);
 	ret = usb_submit_urb(urb, GFP_ATOMIC);
+	if (!ret)
+		return;
+	usb_unanchor_urb(urb);
+
 	if (ret == -ENODEV)
 		netif_device_detach(netdev);
-	else if (ret)
+	else
 		netdev_err(netdev,
 			   "%s: failed to resubmit read bulk urb: %pe\n",
 			   __func__, ERR_PTR(ret));
 }


 static void f81604_read_int_callback(struct urb *urb)
 {
 	struct f81604_int_data *data = urb->transfer_buffer;
 	struct net_device *netdev = urb->context;
 	struct f81604_port_priv *priv;
 	int ret;

 	priv = netdev_priv(netdev);

 	if (!netif_device_present(netdev))
 		return;

 	if (urb->status)
 		netdev_info(netdev, "%s: Int URB aborted: %pe\n", __func__,
 			    ERR_PTR(urb->status));

 	if (urb->actual_length < sizeof(*data)) {
 		netdev_warn(netdev, "%s: short int URB: %u < %zu\n",
 			    __func__, urb->actual_length, sizeof(*data));
 		goto resubmit_urb;
 	}

 	switch (urb->status) {
 	case 0: /* success */
 		break;

 	case -ENOENT:
 	case -EPIPE:
 	case -EPROTO:
 	case -ESHUTDOWN:
 		return;

 	default:
 		goto resubmit_urb;
 	}

 	/* handle Errors */
 	if (data->isrc & (F81604_SJA1000_IRQ_DOI | F81604_SJA1000_IRQ_EI |
 			  F81604_SJA1000_IRQ_BEI | F81604_SJA1000_IRQ_EPI |
 			  F81604_SJA1000_IRQ_ALI))
 		f81604_handle_can_bus_errors(priv, data);

 	/* handle TX */
 	if (priv->can.state != CAN_STATE_BUS_OFF &&
 	    (data->isrc & F81604_SJA1000_IRQ_TI))
 		f81604_handle_tx(priv, data);

 resubmit_urb:
+	usb_anchor_urb(urb, &priv->urbs_anchor);
 	ret = usb_submit_urb(urb, GFP_ATOMIC);
+	if (!ret)
+		return;
+	usb_unanchor_urb(urb);
+
 	if (ret == -ENODEV)
 		netif_device_detach(netdev);
-	else if (ret)
+	else
 		netdev_err(netdev, "%s: failed to resubmit int urb: %pe\n",
 			   __func__, ERR_PTR(ret));
 }



